/**
 * withAndroidPushSetup — Expo config plugin (japa#264).
 *
 * `android/` is generated by prebuild (CNG) and gitignored, so everything
 * Android needs for push in a real build has to be applied from here:
 *
 *  1. Small status-bar icon: copies the white-on-transparent glyph
 *     (src/assets/images/notification-icon.png) to
 *     res/drawable/notification_icon.png and points
 *     `com.google.firebase.messaging.default_notification_icon` at it.
 *     Without it Android renders the coloured app icon as a white square.
 *  2. Default channel id: sets
 *     `com.google.firebase.messaging.default_notification_channel_id` so
 *     notification-payload pushes (shown by the system while the app is
 *     closed) land in our channel instead of a generic "Miscellaneous" one.
 *  3. Channel creation: Android 8+ ignores notifications for a channel that
 *     does not exist, and @react-native-firebase/messaging cannot create
 *     channels. We insert a few lines of Kotlin into MainApplication.onCreate
 *     (after super.onCreate()) so the channel exists from the very first process start, before any JS
 *     runs (and also when a push wakes a killed app). Re-creating an existing
 *     channel is a no-op, so this is safe on every launch.
 *
 * The channel id MUST equal ANDROID_PUSH_CHANNEL_ID in
 * src/config/push.ts and the backend's ANDROID_PUSH_CHANNEL_ID (japa#267),
 * which sends it as `android.notification.channelId`.
 */
// Config plugins run in Node as CommonJS, so require() is the supported form.
/* eslint-disable @typescript-eslint/no-require-imports */
const fs = require('fs');
const path = require('path');
const {
  withAndroidManifest,
  withDangerousMod,
  withMainApplication,
  AndroidConfig,
} = require('expo/config-plugins');
/* eslint-enable @typescript-eslint/no-require-imports */

// Keep in sync with src/config/push.ts and backend japa#267 (see above).
const CHANNEL_ID = 'default';
// User-visible name in Android's per-app notification settings.
const CHANNEL_NAME = 'Seli notifications';

// Source of the small icon, relative to the project root.
const ICON_SRC = 'src/assets/images/notification-icon.png';

// Marker so running prebuild twice never inserts the Kotlin block twice.
const MARKER = '// seli: push channel (japa#264)';

const KOTLIN_IMPORTS = [
  'import android.app.NotificationChannel',
  'import android.app.NotificationManager',
  'import android.os.Build',
];

// Inserted right after super.onCreate() in onCreate() (context is ready). NotificationChannel needs API 26+.
const KOTLIN_BODY = `    ${MARKER}
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
      val manager = getSystemService(NotificationManager::class.java)
      manager.createNotificationChannel(
        NotificationChannel("${CHANNEL_ID}", "${CHANNEL_NAME}", NotificationManager.IMPORTANCE_HIGH)
      )
    }
`;

/** Adds or replaces one <meta-data> entry on <application>. */
function setMeta(application, name, resource) {
  application['meta-data'] ??= [];
  const list = application['meta-data'];
  const existing = list.find((m) => m.$['android:name'] === name);
  const attrs = { 'android:name': name, 'android:resource': resource };
  if (existing) {
    existing.$ = { ...existing.$, ...attrs };
  } else {
    list.push({ $: attrs });
  }
}

/** Steps 1 + 2: manifest meta-data. */
function withManifestMeta(config) {
  return withAndroidManifest(config, (cfg) => {
    const application = AndroidConfig.Manifest.getMainApplicationOrThrow(
      cfg.modResults,
    );
    setMeta(
      application,
      'com.google.firebase.messaging.default_notification_icon',
      '@drawable/notification_icon',
    );
    // default_notification_channel_id takes a string value, not a resource.
    application['meta-data'] ??= [];
    const key = 'com.google.firebase.messaging.default_notification_channel_id';
    const found = application['meta-data'].find(
      (m) => m.$['android:name'] === key,
    );
    if (found) found.$['android:value'] = CHANNEL_ID;
    else
      application['meta-data'].push({
        $: { 'android:name': key, 'android:value': CHANNEL_ID },
      });
    return cfg;
  });
}

/** Step 1: copy the icon into the generated res/drawable folder. */
function withIconFile(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const root = cfg.modRequest.projectRoot;
      const dest = path.join(
        cfg.modRequest.platformProjectRoot,
        'app/src/main/res/drawable',
      );
      fs.mkdirSync(dest, { recursive: true });
      fs.copyFileSync(
        path.join(root, ICON_SRC),
        path.join(dest, 'notification_icon.png'),
      );
      return cfg;
    },
  ]);
}

/** Step 3: create the channel in MainApplication.onCreate. */
function withChannelCreation(config) {
  return withMainApplication(config, (cfg) => {
    const { language, contents } = cfg.modResults;
    if (language !== 'kt') {
      throw new Error('withAndroidPushSetup: expected Kotlin MainApplication');
    }
    if (contents.includes(MARKER)) return cfg; // idempotent
    let out = contents;
    // Add only the imports the file does not already have.
    const missing = KOTLIN_IMPORTS.filter((i) => !out.includes(i));
    out = out.replace(/(^package .*\n)/m, `$1\n${missing.join('\n')}\n`);
    const hook =
      /override fun onCreate\(\) \{\n(?:.*\n)*?\s*super\.onCreate\(\)\n/;
    // Fail loudly rather than silently ship a build with no channel.
    if (!hook.test(out)) {
      throw new Error('withAndroidPushSetup: no onCreate() in MainApplication');
    }
    out = out.replace(hook, (m) => m + KOTLIN_BODY);
    cfg.modResults.contents = out;
    return cfg;
  });
}

module.exports = function withAndroidPushSetup(config) {
  config = withManifestMeta(config);
  config = withIconFile(config);
  return withChannelCreation(config);
};
